CREATE TABLE "contabilidade_mensal" ("id" TEXT NOT NULL, "empreendimentoId" TEXT NOT NULL, "mes" INTEGER NOT NULL, "ano" INTEGER NOT NULL, "poc" DECIMAL(12,5), "custoIncorridoMensal" DECIMAL(18,2), "custoIncorridoAcumulado" DECIMAL(18,2), "estoque" DECIMAL(18,2), "custoApropriadoMensal" DECIMAL(18,2), "terreno" DECIMAL(18,2), "empresaSienge" TEXT, "receitaImportadaEm" TIMESTAMP(3), "estoqueImportadoEm" TIMESTAMP(3), "balanceteImportadoEm" TIMESTAMP(3), CONSTRAINT "contabilidade_mensal_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "contabilidade_mensal_empreendimentoId_mes_ano_key" ON "contabilidade_mensal"("empreendimentoId","mes","ano");
ALTER TABLE "contabilidade_mensal" ADD CONSTRAINT "contabilidade_mensal_empreendimentoId_fkey" FOREIGN KEY ("empreendimentoId") REFERENCES "empreendimentos"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
CREATE TABLE "aditivos_contabeis" ("id" TEXT NOT NULL, "empreendimentoId" TEXT NOT NULL, "mes" INTEGER NOT NULL, "ano" INTEGER NOT NULL, "valor" DECIMAL(18,2) NOT NULL, "observacao" TEXT, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "aditivos_contabeis_pkey" PRIMARY KEY ("id"));
ALTER TABLE "aditivos_contabeis" ADD CONSTRAINT "aditivos_contabeis_empreendimentoId_fkey" FOREIGN KEY ("empreendimentoId") REFERENCES "empreendimentos"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
CREATE TABLE "mapeamentos_contabeis" ("id" TEXT NOT NULL, "empresaSienge" TEXT NOT NULL, "contaConstrucao" TEXT NOT NULL, "contaTransferencia" TEXT NOT NULL, "contaTerreno" TEXT NOT NULL, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "mapeamentos_contabeis_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "mapeamentos_contabeis_empresaSienge_key" ON "mapeamentos_contabeis"("empresaSienge");
